---
&#34;.join([d.page_content for d in docs]) return {&#34;context&#34;: context}Graph với RAG# def build_rag_graph(): graph = StateGraph(AgentState) graph.add_node(&#34;retrieve&#34;, retrieve_node) graph.add_node(&#34;generate&#34;, generate_node) graph.set_entry_point(&#34;retrieve&#34;) graph.add_edge(&#34;retrieve&#34;, &#34;generate&#34;) graph.add_edge(&#34;generate&#34;, END) return graph.compile()Streaming Response# from fastapi.responses import StreamingResponse @router.post(&#34;/chat/stream&#34;) async def chat_stream(request: ChatRequest): async def generate(): async for chunk in agent.astream({&#34;query&#34;: request.message}): yield f&#34;data: {json.dumps(chunk)}

&#34; return StreamingResponse(generate(), media_type=&#34;text/event-stream&#34;)Pydantic Settings Pattern# from pydantic_settings import BaseSettings class Settings(BaseSettings): api_key: str = &#34;&#34; # Required in .env model: str = &#34;gpt-4o-mini&#34; # Default model_config = {&#34;env_file&#34;: &#34;.env&#34;}FastAPI Lifespan Pattern# from contextlib import asynccontextmanager @asynccontextmanager async def lifespan(app: FastAPI): # Startup print(&#34;Starting app...&#34;) yield # Shutdown print(&#34;Shutting down...&#34;) app = FastAPI(lifespan=lifespan)

